// seed: tests/seed.parent.spec.ts
// Без выбора «רמת כתיבה להתחלה» уровень по возрасту: ≤6→1, 7→2, 8–9→3, 10+→4 (комментарий программиста, решение 01.11).
// Берём только возрасты, где ответ не зависит от того, прошёл ли день рождения: 5 (→1), 9 (→3; 8 или 9), 12 (→4; 11 или 12).
// Бакет 7→2 не автоматизирован: по одному году рождения 6/7 лет неразличимы.
// Создаёт 3 детей QA-AUTO-… — удаляет пользователь (нужен пароль родителя), имена и id — в annotations «cleanup».
// Не прогонять при записи — запуск только по /qa-regress.
import * as path from 'path';
import { test } from '../../fixtures';
import {
  annotateCleanup,
  birthYearForAge,
  createChildWithLevels,
  expectWritingLevelInProfile,
  qaChildName,
} from '../writing-submit/writing.helpers';

test.use({ storageState: path.resolve(__dirname, '../../../auth/parent.json') });

test.describe('Стартовый уровень письма — по возрасту, если родитель не выбрал (autotest-writer)', () => {
  test('Без выбора уровня: 5 лет → «כתיבה: 1 / 4», 9 лет → 3, 12 лет → 4 @desktop @data #be58fd', async ({ page }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const cases: { age: number; level: number }[] = [
      { age: 5, level: 1 },
      { age: 9, level: 3 },
      { age: 12, level: 4 },
    ];
    for (const c of cases) {
      await test.step(`${c.age} лет → ${c.level} / 4`, async () => {
        const name = qaChildName();
        const id = await createChildWithLevels(page, name, { birthYear: birthYearForAge(c.age) });
        annotateCleanup(testInfo, name, id);
        // AC2 / комментарий: «לא בחר → לפי הגיל»
        await expectWritingLevelInProfile(page, id, c.level);
      });
    }
  });
});
